	private record Facts(ValueExpr expression, boolean canSucceed, boolean expressionError,
			EnumSet<EbvOutcome> successfulEbvs, Value fixedValue) {
		private EnumSet<EbvOutcome> outcomes() {
			EnumSet<EbvOutcome> result = successfulEbvs.clone();
			if (expressionError) {
				result.add(EbvOutcome.ERROR);
			}
			return result;
		}
	}
